#!/usr/bin/env bash
# =============================================================================
# setup_pioneer_nav.sh
# Auto-generated master setup script for the pioneer_nav_ws (scoutbot AGV)
# ROS2 Humble waypoint-navigation project.
#
# This single script:
#   1. Verifies host environment (Ubuntu 22.04 + ROS 2 Humble + colcon).
#   2. Installs missing apt dependencies (idempotent).
#   3. Creates the workspace and writes every source/config/launch file.
#   4. Builds the workspace with colcon.
#   5. Sources install/setup.bash.
#   6. Runs offline static checks (tools/check_workspace.sh).
#   7. Optionally launches scout_full_stack and runs runtime diagnostics.
#
# USAGE
#   bash setup_pioneer_nav.sh                # build + static check, no launch
#   bash setup_pioneer_nav.sh --launch       # build + launch full stack
#   bash setup_pioneer_nav.sh --no-build     # write files only
#   bash setup_pioneer_nav.sh --force        # overwrite existing files
#   bash setup_pioneer_nav.sh --dry-run      # list every file it would write
#
# REGENERATION
#   This script was generated by tools/_gen_master_script.py.
#   To regenerate after editing any file under src/, run:
#       python3 tools/_gen_master_script.py
# =============================================================================
set -uo pipefail

# ---- options ----------------------------------------------------------------
WS_NAME="pioneer_nav_ws"
WS_DIR="${WS_DIR:-${HOME}/${WS_NAME}}"
DO_BUILD=1
DO_LAUNCH=0
FORCE=0
DRY_RUN=0
for arg in "$@"; do
  case "${arg}" in
    --launch)   DO_LAUNCH=1 ;;
    --no-build) DO_BUILD=0  ;;
    --force)    FORCE=1     ;;
    --dry-run)  DRY_RUN=1   ;;
    -h|--help)
      sed -n '2,30p' "$0"; exit 0;;
    *) echo "Unknown option: ${arg}" >&2; exit 1;;
  esac
done

GREEN='\033[0;32m'; RED='\033[0;31m'; YEL='\033[0;33m'; NC='\033[0m'
say()  { echo -e "${GREEN}==>${NC} $*"; }
warn() { echo -e "${YEL}==>${NC} $*"; }
fail() { echo -e "${RED}!!${NC}  $*" >&2; exit 1; }

# ---- environment checks -----------------------------------------------------
check_env() {
  say "Checking host environment"
  if [[ -f /etc/os-release ]]; then
    . /etc/os-release
    if [[ "${ID:-}" != "ubuntu" || "${VERSION_ID:-}" != "22.04" ]]; then
      warn "Detected ${ID:-?} ${VERSION_ID:-?}; ROS2 Humble targets Ubuntu 22.04 (jammy). Continuing anyway."
    else
      echo "  OK Ubuntu 22.04"
    fi
  fi
  if [[ -z "${ROS_DISTRO:-}" ]]; then
    warn "ROS_DISTRO not set in this shell. Trying /opt/ros/humble/setup.bash"
    if [[ -f /opt/ros/humble/setup.bash ]]; then
      # shellcheck disable=SC1091
      source /opt/ros/humble/setup.bash
    else
      fail "ROS 2 Humble not found. Install ros-humble-desktop first."
    fi
  fi
  echo "  OK ROS_DISTRO=${ROS_DISTRO}"
  command -v colcon >/dev/null 2>&1 || fail "colcon not found (sudo apt install python3-colcon-common-extensions)"
  command -v xacro  >/dev/null 2>&1 || fail "xacro not found (sudo apt install ros-humble-xacro)"
  echo "  OK colcon + xacro"
}

# ---- apt dependencies (idempotent) ------------------------------------------
install_deps() {
  say "Installing apt dependencies (sudo required, idempotent)"
  local pkgs=(
    ros-humble-xacro
    ros-humble-robot-state-publisher
    ros-humble-joint-state-publisher
    ros-humble-joint-state-publisher-gui
    ros-humble-rviz2
    ros-humble-gazebo-ros-pkgs
    ros-humble-gazebo-ros2-control
    ros-humble-ros2-control
    ros-humble-ros2-controllers
    ros-humble-controller-manager
    ros-humble-diff-drive-controller
    ros-humble-joint-state-broadcaster
    ros-humble-tf-transformations
    ros-humble-teleop-twist-keyboard
    python3-colcon-common-extensions
    python3-yaml
    python3-pytest
  )
  if sudo -n true 2>/dev/null; then
    sudo apt-get update -y
    sudo apt-get install -y --no-install-recommends "${pkgs[@]}"
  else
    warn "sudo not available without password; skipping apt install. Ensure these are present:"
    printf '  - %s\n' "${pkgs[@]}"
  fi
}

# ---- write_file: heredoc helper ---------------------------------------------
# Usage: write_file <relative-path>  (content read from stdin until WRITE_EOF)
write_file() {
  local rel="$1"
  local abs="${WS_DIR}/${rel}"
  if (( DRY_RUN )); then
    printf '  WOULD WRITE %s\n' "${rel}"
    cat >/dev/null
    return 0
  fi
  if [[ -e "${abs}" && ${FORCE} -eq 0 ]]; then
    printf '  SKIP   %s (exists; use --force to overwrite)\n' "${rel}"
    cat >/dev/null
    return 0
  fi
  mkdir -p "$(dirname "${abs}")"
  cat > "${abs}"
  printf '  WRITE  %s\n' "${rel}"
}

write_all_files() {
  say "Writing files into ${WS_DIR}"
  mkdir -p "${WS_DIR}"

  write_file ARCHITECTURE.md <<'WRITE_EOF'
