WRITE_EOF
  write_file src/scoutbot_control/config/controllers.yaml <<'WRITE_EOF'
# =============================================================================
# controllers.yaml
# Loaded inside Gazebo by the gazebo_ros2_control plugin (URDF <parameters>).
# Defines the controller_manager and two controllers:
#   * scoutbot_joint_broadcaster (publishes joint_states)
#   * scoutbot_base_controller   (diff_drive_controller)
#
# CRITICAL DESIGN NOTE
# --------------------
# Every parameter that also appears in the URDF (wheel_radius, wheel_separation)
# must match the URDF's xacro:property values exactly. Mismatch causes silent
# odometry drift, which was a documented failure of the previous project.
# =============================================================================

# Top-level node name. The /scoutbot namespace prefix comes from the
# gazebo_ros2_control plugin's <namespace> tag in scoutbot.urdf.xacro,
# so the fully qualified node is /scoutbot/controller_manager.
controller_manager:
  ros__parameters:
    # Hard-locked control loop rate. Must be >= the navigator's 50 Hz output
    # rate; we run 100 Hz so commands are not dropped by under-sampling.
    update_rate: 100  # Hz

    # ---- controller registry --------------------------------------------------
    scoutbot_joint_broadcaster:
      type: joint_state_broadcaster/JointStateBroadcaster

    scoutbot_base_controller:
      type: diff_drive_controller/DiffDriveController


# =============================================================================
# scoutbot_joint_broadcaster
# Reads joint state interfaces and republishes /scoutbot/joint_states. RSP
# consumes that to broadcast the rest of the TF tree.
# =============================================================================
scoutbot_joint_broadcaster:
  ros__parameters:
    # Empty list -> broadcast every joint declared in <ros2_control>.
    joints: []
    extra_joints: []


# =============================================================================
# scoutbot_base_controller (diff_drive_controller)
# Subscribes:  /scoutbot/cmd_vel       (geometry_msgs/Twist)        (remapped below)
# Publishes:   /scoutbot/odom          (nav_msgs/Odometry)          (remapped below)
# Broadcasts:  TF: scout_odom -> scout_base_footprint
# =============================================================================
scoutbot_base_controller:
  ros__parameters:

    # ---- joints (must match URDF <ros2_control>) -----------------------------
    left_wheel_names:  ["scout_left_wheel_joint"]
    right_wheel_names: ["scout_right_wheel_joint"]

    # ---- kinematics (must match URDF xacro:properties) -----------------------
    wheel_separation: 0.40   # [m] track width
    wheel_radius:     0.10   # [m]

    # If the simulator's reported separation/radius differ slightly from URDF
    # (e.g., due to URDF rounding), these multipliers compensate. Default 1.0.
    wheel_separation_multiplier: 1.0
    left_wheel_radius_multiplier:  1.0
    right_wheel_radius_multiplier: 1.0

    # ---- topic remaps --------------------------------------------------------
    # diff_drive_controller default is /<ns>/<controller_name>/cmd_vel_unstamped
    # which is awkward. Use the conventional /scoutbot/cmd_vel and /scoutbot/odom.
    # The 'tf' frames are absolute (no namespace prefix) by design.
    publish_rate: 50.0          # [Hz] odom + TF publish rate
    odom_frame_id:  scout_odom
    base_frame_id:  scout_base_footprint
    pose_covariance_diagonal:  [0.001, 0.001, 0.0, 0.0, 0.0, 0.01]
    twist_covariance_diagonal: [0.001, 0.001, 0.0, 0.0, 0.0, 0.01]

    # Source of truth for TF: the controller publishes scout_odom -> scout_base_footprint.
    # RSP publishes the static chain scout_base_footprint -> {wheels, sensors}.
    # No other publisher writes scout_odom -> scout_base_footprint.
    enable_odom_tf: true
    open_loop: false                  # use measured wheel velocities
    position_feedback: true

    # ---- velocity / acceleration limits --------------------------------------
    # These are hard caps applied AFTER the navigator's PID. They protect the
    # robot from any runaway PID output (defense in depth).
    linear:
      x:
        has_velocity_limits:    true
        has_acceleration_limits: true
        has_jerk_limits:        false
        max_velocity:        1.0   # [m/s]
        min_velocity:       -1.0
        max_acceleration:    1.5   # [m/s^2]
        min_acceleration:   -1.5
    angular:
      z:
        has_velocity_limits:    true
        has_acceleration_limits: true
        has_jerk_limits:        false
        max_velocity:        2.0   # [rad/s]
        min_velocity:       -2.0
        max_acceleration:    3.0   # [rad/s^2]
        min_acceleration:   -3.0

    # ---- safety: stop if no command for cmd_vel_timeout seconds --------------
    cmd_vel_timeout: 0.5             # [s]

    # The unstamped Twist topic is what teleop_twist_keyboard publishes by default;
    # the ros2_humble diff_drive_controller subscribes to it under the controller
    # name. We rely on a launch-time 'remap' to expose it as /scoutbot/cmd_vel.
    use_stamped_vel: false
WRITE_EOF
  write_file src/scoutbot_control/config/pid_gains.yaml <<'WRITE_EOF'
# =============================================================================
# pid_gains.yaml
# Gains and thresholds for the navigator's two PID loops, plus state-machine
# tuning. Loaded by waypoint_navigator at start-up via declare_parameter().
#
# Ranges and units are documented per parameter. Defaults are tuned for:
#   wheel_radius     = 0.10 m
#   wheel_separation = 0.40 m
#   chassis_mass     = 6.0  kg
#   max linear  = 1.0 m/s, max angular = 2.0 rad/s   (matches controllers.yaml)
# =============================================================================

waypoint_navigator:
  ros__parameters:

    # ---- topic / frame configuration -----------------------------------------
    odom_topic:      /scoutbot/odom
    cmd_vel_topic:   /scoutbot/cmd_vel
    status_topic:    /scoutbot/nav_status
    odom_frame:      scout_odom

    # ---- timing --------------------------------------------------------------
    control_frequency_hz:  50.0   # control-loop rate. 50 Hz is well below the
                                  # 100 Hz CM update_rate, so no command is dropped.
    status_publish_hz:      2.0   # diagnostic publish rate. Decoupled from
                                  # control loop -> no terminal flooding.

    # ---- linear PID (input: distance_to_goal [m], output: v [m/s]) -----------
    linear_kp: 0.8
    linear_ki: 0.0    # integral kept off; distance always >= 0 so windup risk
    linear_kd: 0.05
    linear_max_output:    1.0     # hard ceiling [m/s] -- matches controllers.yaml
    linear_min_output:    0.0     # never reverse during DRIVE
    linear_integral_clamp: 0.5    # |i_term| <= this
    linear_deadband:      0.01    # |output| < this -> 0  (kills jitter)

    # ---- angular PID (input: heading_error [rad], output: omega [rad/s]) ----
    angular_kp: 1.5
    angular_ki: 0.0
    angular_kd: 0.10
    angular_max_output:    2.0    # [rad/s] -- matches controllers.yaml
    angular_min_output:   -2.0
    angular_integral_clamp: 0.8
    angular_deadband:      0.02   # [rad/s]

    # ---- state-machine thresholds (asymmetric -> hysteresis -> no oscillation)
    align_enter_threshold: 0.40   # [rad]   DRIVE  -> ALIGN_HEADING when |err| >=
    align_exit_threshold:  0.05   # [rad]   ALIGN_HEADING -> DRIVE  when |err| <=
    goal_enter_threshold:  0.30   # [m]     DRIVE  -> FINE_APPROACH when dist <=
    goal_tolerance:        0.05   # [m]     FINE_APPROACH -> REACHED when dist <=
    final_yaw_tolerance:   0.05   # [rad]   ALIGN_FINAL -> next waypoint

    # ---- fine-approach speeds (gentler -> no overshoot at the goal) ---------
    fine_approach_max_linear:  0.20   # [m/s]
    fine_approach_max_angular: 0.80   # [rad/s]

    # ---- safety --------------------------------------------------------------
    odom_stale_timeout: 1.0       # [s] If no odom for this long, stop the robot
                                  # and log an error (throttled).
WRITE_EOF
  write_file src/scoutbot_control/launch/spawn_controllers.launch.py <<'WRITE_EOF'
"""
spawn_controllers.launch.py
===========================
Spawns the two ros2_control controllers on the controller_manager that
gazebo_ros2_control creates inside Gazebo. Uses an event chain so that:

    joint_state_broadcaster spawn   ->   ON EXIT   ->   diff_drive spawn

This sequencing prevents the previous project's "controller stuck in
waiting" failure: the diff-drive spawner is never invoked until the
joint_state_broadcaster spawner has fully exited (which itself only exits
once the controller_manager has accepted the load+activate request).

Both spawners reach the controller_manager via the namespaced service
``/scoutbot/controller_manager/...``; we set ``--controller-manager``
explicitly to make this unambiguous.
"""

from launch import LaunchDescription
from launch.actions import DeclareLaunchArgument, RegisterEventHandler
from launch.event_handlers import OnProcessExit
from launch.substitutions import LaunchConfiguration
from launch_ros.actions import Node


def generate_launch_description() -> LaunchDescription:
    arg_cm_ns = DeclareLaunchArgument(
        'controller_manager_ns',
        default_value='/scoutbot/controller_manager',
        description='Fully-qualified controller_manager service namespace.',
    )

    # Spawner #1: joint_state_broadcaster -- must come first so subsequent
    # controllers can rely on a /joint_states topic for diagnostics.
    spawn_jsb = Node(
        package='controller_manager',
        executable='spawner',
        name='spawn_scoutbot_joint_broadcaster',
        arguments=[
            'scoutbot_joint_broadcaster',
            '--controller-manager', LaunchConfiguration('controller_manager_ns'),
        ],
        output='screen',
    )

    # Spawner #2: diff_drive_controller -- only fires AFTER spawner #1 exits.
    spawn_dd = Node(
        package='controller_manager',
        executable='spawner',
        name='spawn_scoutbot_base_controller',
        arguments=[
            'scoutbot_base_controller',
            '--controller-manager', LaunchConfiguration('controller_manager_ns'),
        ],
        output='screen',
    )

    chain = RegisterEventHandler(
        OnProcessExit(target_action=spawn_jsb, on_exit=[spawn_dd])
    )

    return LaunchDescription([arg_cm_ns, spawn_jsb, chain])
