  scout_odom
  scout_base_footprint
  scout_base_link
  scout_left_wheel_link
  scout_right_wheel_link
  scout_caster_link
  scout_imu_link
)

failed=0

echo "==> [1/5] Live nodes"
have=$(ros2 node list 2>/dev/null || true)
for n in "${EXPECTED_NODES[@]}"; do
  if grep -qx "$n" <<<"${have}"; then
    printf '  OK    %s\n' "$n"
  else
    printf '  MISS  %s\n' "$n"
    failed=1
  fi
done

echo
echo "==> [2/5] Live topics"
have=$(ros2 topic list 2>/dev/null || true)
for t in "${EXPECTED_TOPICS[@]}"; do
  if grep -qx "$t" <<<"${have}"; then
    printf '  OK    %s\n' "$t"
  else
    printf '  MISS  %s\n' "$t"
    failed=1
  fi
done

echo
echo "==> [3/5] Loaded controllers"
have=$(ros2 control list_controllers --controller-manager /scoutbot/controller_manager 2>/dev/null || true)
for c in "${EXPECTED_CONTROLLERS[@]}"; do
  if grep -q "${c}.*active" <<<"${have}"; then
    printf '  OK    %-30s active\n' "$c"
  else
    printf '  MISS  %-30s not active (have: "%s")\n' "$c" "${have}"
    failed=1
  fi
done

echo
echo "==> [4/5] /scoutbot/cmd_vel publish rate (5 s sample)"
hz=$(timeout 6 ros2 topic hz /scoutbot/cmd_vel 2>&1 | grep -m1 average | awk '{print $3}')
if [[ -n "${hz}" ]]; then
  printf '  cmd_vel ~ %s Hz (expect ~50)\n' "${hz}"
else
  printf '  FAIL no rate observed in 5 s\n'; failed=1
fi

echo
echo "==> [5/5] TF tree completeness"
tf_view=$(timeout 3 ros2 run tf2_tools view_frames -o /tmp/scout_frames 2>&1 || true)
have=$(ros2 topic echo --once /tf 2>/dev/null || true)
have_static=$(ros2 topic echo --once /tf_static 2>/dev/null || true)
combined="${have}${have_static}"
for f in "${EXPECTED_TF_LINKS[@]}"; do
  if grep -q "frame_id: ${f}" <<<"${combined}" \
     || grep -q "child_frame_id: ${f}" <<<"${combined}"; then
    printf '  OK    %s\n' "$f"
  else
    printf '  WARN  %s not seen yet (try again after the robot moves)\n' "$f"
  fi
done

echo
if [[ ${failed} -eq 0 ]]; then
  echo "==> RUNTIME DIAGNOSTICS PASSED"
  exit 0
else
  echo "==> RUNTIME DIAGNOSTICS FAILED -- inspect missing items above"
  exit 1
fi
WRITE_EOF
  write_file tools/teleop_quickdrive.sh <<'WRITE_EOF'
#!/usr/bin/env bash
# =============================================================================
# tools/teleop_quickdrive.sh
# Convenience wrapper around teleop_twist_keyboard with the correct topic
# remap for the scoutbot. Useful for sanity-checking the diff_drive_controller
# without running the navigator.
#
#   bash tools/teleop_quickdrive.sh
# =============================================================================
set -euo pipefail

if ! command -v ros2 >/dev/null 2>&1; then
  echo "ERROR: ROS 2 environment not sourced. Source install/setup.bash first." >&2
  exit 1
fi

if ! ros2 pkg list 2>/dev/null | grep -q '^teleop_twist_keyboard$'; then
  echo "ERROR: teleop_twist_keyboard not installed." >&2
  echo "       sudo apt install -y ros-humble-teleop-twist-keyboard" >&2
  exit 1
fi

echo "Driving /scoutbot/cmd_vel (i/k/j/l/u/o/m/,/. , q/z to change speed)"
exec ros2 run teleop_twist_keyboard teleop_twist_keyboard \
  --ros-args -r cmd_vel:=/scoutbot/cmd_vel
WRITE_EOF

}

# ---- build, source, verify, launch -----------------------------------------
build_ws() {
  say "Building workspace (colcon build --symlink-install)"
  pushd "${WS_DIR}" >/dev/null
  colcon build --symlink-install --event-handlers console_cohesion+ \
      || fail "colcon build failed"
  popd >/dev/null
}

source_ws() {
  say "Sourcing workspace"
  # shellcheck disable=SC1091
  source "${WS_DIR}/install/setup.bash"
  echo "  OK packages now visible:"
  ros2 pkg list 2>/dev/null | grep '^scoutbot_' | sed 's/^/    /'
}

static_check() {
  say "Running offline static checks"
  bash "${WS_DIR}/tools/check_workspace.sh" || fail "static check failed"
}

launch_full_stack() {
  say "Launching scout_full_stack.launch.py (Ctrl-C to stop)"
  warn "Open a SECOND terminal and run:"
  echo  "    source ${WS_DIR}/install/setup.bash"
  echo  "    bash   ${WS_DIR}/tools/diagnose_runtime.sh"
  ros2 launch scoutbot_bringup scout_full_stack.launch.py
}

# ---- main flow --------------------------------------------------------------
check_env
if (( ! DRY_RUN )); then install_deps; fi
write_all_files
if (( DRY_RUN )); then
  say "DRY RUN complete. No files written."
  exit 0
fi

if (( DO_BUILD )); then
  build_ws
  source_ws
  static_check
  if (( DO_LAUNCH )); then
    launch_full_stack
  else
    say "Build + static check OK. Launch with:  bash $0 --launch"
  fi
else
  say "Files written (build skipped). Run colcon build manually:"
  echo "    cd ${WS_DIR} && colcon build --symlink-install"
fi
